// Кейс: .qa/tests/monitoring/MON-025.md · план: .qa/e2e-app/specs/app.md (1.30)
// Мониторинг → фон 10 с (mobile: backgroundApp) → возврат (лист «הניטור הופסק», если есть, → «המשך ניטור») →
// в «היסטוריית אירועים» после «האפליקציה ירדה לרקע» ровно одно «הניטור חזר לפעול» за 30 с и ни одного «המצלמה הפסיקה לפעול».
// Источник: «מה רצוי» #7b5462 + проверка 01.11 (фон 10 с: ירדה לרקע 0:04:08 → חזר לפעול 0:04:19 один раз; скрин results/2026-11-01-7b5462-bg.png).
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1.
import { by, assert } from '../../lib/appium.mjs';
import {
  requireMonitoringOptIn, startMonitoring, endMonitoring, waitTimer,
  EV, collectEvents, countOf, fmtEvents,
} from '../../lib/monitoring.mjs';

export const name = 'Фон 10 с → «האפליקציה ירדה לרקע» → ровно одно «הניטור חזר לפעול» за 30 с, без «המצלמה הפסיקה לפעול» #7b5462 @iphone @app @data';

export default async function (app) {
  requireMonitoringOptIn();
  await startMonitoring(app);
  await waitTimer(app, 5);

  // 1. Фон 10 с, возврат.
  await app.exec('mobile: backgroundApp', { seconds: 10 });
  await app.activate();

  // 2. Лист «הניטור הופסק» — если показан, «המשך ניטור».
  try {
    await app.waitFor(by.contains('הניטור הופסק'), { timeout: 10000, what: 'лист «הניטור הופסק»' });
    await app.tap(by.exact('המשך ניטור', 'Button'), { what: '«המשך ניטור» в листе' });
    await app.waitGone(by.contains('הניטור הופסק'), { what: 'лист «הניטור הופסק» закрылся' });
  } catch (e) {
    if (!String(e.message).startsWith('Не найден за')) throw e; // листа нет — не провал
  }
  await app.waitFor(by.exact('תקין'), { timeout: 20000, what: 'статус «תקין» после возврата из фона' });

  // 3. Событие ухода в фон.
  let events = await collectEvents(app);
  const bg = events.filter((e) => e.title === EV.BACKGROUND).pop();
  assert(bg, `в «היסטוריית אירועים» есть «${EV.BACKGROUND}» (есть: ${fmtEvents(events) || 'пусто'})`);

  // 4. 30 с по таймеру мониторинга от ухода в фон (повтор каждые ~8 с — баг #7b5462 — успел бы проявиться ≥ 3 раза).
  await waitTimer(app, bg.t + 30, { timeout: 60000 });
  events = await collectEvents(app);
  console.log(`     события: ${fmtEvents(events)}`);
  const shot = await app.screenshot('7b5462-auto-bg-events').catch(() => undefined);

  const resumed = events.filter((e) => e.title === EV.RESUMED && e.t >= bg.t);
  assert(resumed.length === 1, `после «${EV.BACKGROUND}» ${bg.time} ровно одно «${EV.RESUMED}» (найдено ${resumed.length}: ${resumed.map((e) => e.time).join(', ') || '—'}; скрин ${shot ?? '—'})`);
  assert(resumed[0].t - bg.t <= 30, `«${EV.RESUMED}» в течение 30 с после ухода в фон (${bg.time} → ${resumed[0].time})`);
  const camStopped = countOf(events, EV.CAMERA_STOPPED);
  assert(camStopped === 0, `«${EV.CAMERA_STOPPED}» в «היסטוריית אירועים» нет (найдено ${camStopped}; скрин ${shot ?? '—'})`);

  // 5. Завершить мониторинг (сеанс в истории — тестовые данные).
  await endMonitoring(app);
}
